mapper.select:
SELECT T1.ENTRUST_ID entrustId, T1.ENTRUST_STATUS entrustStatus, T1.PORTFOLIO_ID portfolioId, /*增加投资经理 guyunfei 2019/08/31 start*/ T1.INV_MANAGER_ID invManagerId, /*增加投资经理 guyunfei 2019/08/31 end*/ T2.PORTFOLIO_NAME portfolioName, /*T4.ASSET_TYPE1 assetType1,*/ /*增加三、四级查询字段、zhuyongkang 2019/7/29 start*/ T4.ASSET_TYPE1 assetType1, T4.ASSET_TYPE_10 assetType10, T4.ASSET_TYPE_11 assetType11, /*zhuyongkang 2019/7/29 end*/ T1.FINPROD_ID finprodId, T3.FINPROD_MARKET_ID finprodMarketId, T3.FINPROD_NAME finprodName, T1.PS ps, T1.ENTRUST_AMT entrustAmt, T1.ENTRUST_NUM entrustNum, T1.CCY ccy, T1.VDATE vdate, T1.MDATE mdate, NVL(T5.FINISH_AMT,0) finishAmt, round(NVL(T5.FINISH_AMT,0)/NVL(T1.ENTRUST_AMT,T1.ENTRUST_NUM),4)*100 transactioncom, T1.REMARK remark FROM ETR_ENTRUST T1 LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID INNER JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID INNER JOIN ETR_ENTRUST_ADD T4 ON T4.ENTRUST_ID = T1.ENTRUST_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(NVL(FINISH_AMT,0)) FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY T6 ON T2.PORTFOLIO_ID = T6.PORTFOLIO_ID
AND T6.USER_ID = #{userId}
AND (T2.PORTFOLIO_ID IN
null) OR T2.PORTFOLIO_ID IN (
#{prot}
or T2.PARENT_PORTFOLIO_ID IN
null) OR T2.PARENT_PORTFOLIO_ID IN (
#{prot}
)
/*新增2、3.4查询判断条件、zhuyongkang 2019/7/29 start*/
AND T4.ASSET_TYPE1 in
#{item}
AND T4.ASSET_TYPE_10 in
#{item}
AND T4.ASSET_TYPE_11 in
#{item}
/*新增3.4查询判断条件、zhuyongkang 2019/7/29 end*/
AND T1.CCY = #{ccy}
AND (T3.FINPROD_MARKET_ID like concat('%',concat(#{finprodId},'%')) OR T3.FINPROD_NAME like concat('%',concat(#{finprodId},'%')))
AND T1.PS=#{ps}
AND T1.ENTRUST_STATUS = #{entrustStatus}
AND T1.VDATE >=to_date(#{startDate},'yyyy-MM-dd')
AND T1.MDATE <=to_date(#{endDate},'yyyy-MM-dd')
AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE2} AND T3.PROFIT_TYPE = #{PROFIT_TYPE}
order by T1.ENTRUST_ID DESC

SELECT T1.PORTFOLIO_ID code, T1.PORTFOLIO_ID name, T1.PORTFOLIO_NAME shortName, T1.PORTFOLIO_ID hidCode FROM PTL_PORTFOLIO T1 INNER JOIN PTL_PORTFOLIO_AUTHORITY T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID AND T2.USER_ID = #{userId}
T1.PORTFOLIO_ID like concat('%',concat(#{param},'%')) OR T1.PORTFOLIO_Name like concat('%',concat(#{param},'%'))
AND T1.PORTFOLIO_TYPE IN (#{portType}, #{portType1})

SELECT FINPROD_MARKET_ID code, FINPROD_MARKET_ID name, FINPROD_ABBR shortName, FINPROD_MARKET_ID hidCode, FINPROD_ID finprodId FROM FIN_PRODUCT
(FINPROD_MARKET_ID like concat('%',concat(#{param},'%')) or FINPROD_ABBR like concat('%',concat(#{param},'%')))
AND FINPROD_TYPE2=#{FINPROD_TYPE_TG_F17,jdbcType=VARCHAR} AND PROFIT_TYPE=#{PROFIT_TYPE_02,jdbcType=VARCHAR}

SELECT T1.PORTFOLIO_ID id, T1.PORTFOLIO_NAME text FROM PTL_PORTFOLIO T1 INNER JOIN PTL_PORTFOLIO_AUTHORITY T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID AND T2.USER_ID = #{userId}
T1.PORTFOLIO_ID = #{initValue}
and (T1.PORTFOLIO_ID like concat('%',concat(#{search},'%')) OR T1.PORTFOLIO_NAME like concat('%',concat(#{search},'%')))
AND T1.PORTFOLIO_TYPE in
#{portType}

SELECT T1.FINPROD_MARKET_ID id, T1.FINPROD_NAME text, T1.FINPROD_NAME, T1.FINPROD_ID, T1.CALENDAR_ID, T1.CCY, T1.VDATE, T1.MDATE,
/*T2.TYPE_6,*/ T2.TYPE_9, T2.TYPE_10, T2.TYPE_11
FROM FIN_PRODUCT T1 LEFT JOIN FIN_PRODUCT_TYPE T2 ON T1.FINPROD_ID = T2.FINPROD_ID
T1.FINPROD_MARKET_ID = #{initValue}
and (T1.FINPROD_MARKET_ID like concat('%',concat(#{search},'%')) or T1.FINPROD_NAME like concat('%',concat(#{search},'%')))
AND T1.FINPROD_TYPE2=#{FINPROD_TYPE_TG_F17,jdbcType=VARCHAR} AND T1.PROFIT_TYPE=#{PROFIT_TYPE_02,jdbcType=VARCHAR}
